import assert from "node:assert/strict";
import { test } from "node:test";
import { createServer } from "node:http";
import { once } from "node:events";
import { ApiError } from "../src/api.ts";
import { branchOf, byBranch, isUntagged, listResources, matches, toLabeledResource } from "../src/filter.ts";
import { buildPlan } from "../src/plan.ts";
import { summarize } from "../src/report.ts";

const resource = (id: string, fields: Record<string, unknown> = {}) => toLabeledResource({
  id, type: "instance", name: id, ...fields,
});

test("labels survive normalization and their keys, not values, are case-insensitive", () => {
  for (const key of ["branch", "Branch", "BRANCH", "bRaNcH"]) {
    const r = resource(key, { labels: { [key]: "feat-ledger", Team: "payments" } });
    assert.equal(branchOf(r), "feat-ledger");
    assert.equal(isUntagged(r), false);
    assert.ok(matches(r, [["branch", "feat-ledger"], ["TEAM", "payments"]]));
    assert.equal(matches(r, [["branch", "FEAT-LEDGER"]]), false);
    assert.equal(buildPlan([r], "FEAT-LEDGER").steps.length, 0);
  }
  assert.equal(branchOf(resource("legacy", { tags: { branch: "legacy" } })), "legacy");
  assert.equal(branchOf(resource("none")), undefined);
  assert.equal(branchOf(resource("both", {
    tags: { branch: "legacy" }, labels: { Branch: "other" },
  })), "legacy");
});

test("labels participate in listing and are not garbage-collection candidates", () => {
  const resources = [resource("cdk", { labels: { Branch: "feat-ledger" }, cost_month_cents: 123 }), resource("orphan")];
  assert.deepEqual(byBranch(resources).get("feat-ledger")?.map(r => r.id), ["cdk"]);
  assert.match(summarize(resources), /feat-ledger\s+1\s+\$1\.23/);
  assert.match(summarize(resources), /1 untagged resources/);
  assert.deepEqual(resources.filter(isUntagged).map(r => r.id), ["orphan"]);
});

test("mixed provisioners form one complete, dependency-ordered branch plan", () => {
  const resources = [
    resource("network", { tags: { branch: "feat-ledger" }, stack_id: "stk-feat-ledger" }),
    resource("boot", { stack_id: "stk-feat-ledger" }),
    resource("worker", { labels: { Branch: "feat-ledger" }, depends_on: ["network", "boot"], stack_id: "cdk-stack" }),
    resource("cdk-boot", { stack_id: "cdk-stack" }),
    resource("disk", { labels: { BRANCH: "feat-ledger" } }),
    resource("snapshot", { labels: { branch: "feat-ledger" }, depends_on: ["disk"] }),
    resource("other", { labels: { Branch: "feat-other" }, stack_id: "cdk-stack" }),
    resource("orphan"),
  ];
  const plan = buildPlan(resources, "feat-ledger");
  assert.deepEqual(plan.blocked, []);
  const ids = plan.steps.map(s => s.id);
  assert.deepEqual([...ids].sort(), ["network", "boot", "worker", "cdk-boot", "disk", "snapshot"].sort());
  for (const r of resources.filter(r => ids.includes(r.id))) {
    for (const dependency of r.depends_on) assert.ok(ids.indexOf(r.id) < ids.indexOf(dependency));
  }
});

test("genuine external dependents still block teardown, without expanding ownership", () => {
  const plan = buildPlan([
    resource("network", { tags: { branch: "feat-ledger" } }),
    resource("external", { labels: { Branch: "feat-other" }, depends_on: ["network"] }),
    resource("unowned", { depends_on: ["network"] }),
  ], "feat-ledger");
  assert.deepEqual(plan.steps.map(s => s.id), ["network"]);
  assert.deepEqual(plan.blocked, [{ id: "network", dependents: ["external", "unowned"] }]);
});

test("service listing preserves labels through pagination, retries 429, and surfaces errors", async (t) => {
  const paths: string[] = [];
  let limited = false;
  let unauthorized = false;
  const server = createServer((req, res) => {
    assert.equal(req.headers.authorization, "Bearer test-token");
    paths.push(req.url!);
    res.setHeader("content-type", "application/json");
    if (unauthorized) {
      res.writeHead(401).end(JSON.stringify({ error: "unauthorized" }));
    } else if (!limited) {
      limited = true;
      res.writeHead(429, { "retry-after": "0" }).end("{}");
    } else if (req.url?.includes("cursor=0&")) {
      res.end(JSON.stringify({ resources: [{ id: "one", labels: { Branch: "feat-ledger" } }], next_cursor: "next/page" }));
    } else {
      res.end(JSON.stringify({ resources: [{ id: "two", labels: { BRANCH: "feat-ledger" } }], next_cursor: null }));
    }
  });
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  t.after(() => server.close());
  const address = server.address() as { port: number };
  const config = { baseUrl: `http://127.0.0.1:${address.port}`, token: "test-token" };
  const logs: string[] = [];
  const resources = await listResources(config, message => logs.push(message));
  assert.deepEqual(resources.map(branchOf), ["feat-ledger", "feat-ledger"]);
  assert.deepEqual(paths, ["/v1/resources?cursor=0&limit=20", "/v1/resources?cursor=0&limit=20", "/v1/resources?cursor=next%2Fpage&limit=20"]);
  assert.equal(logs.length, 1);
  unauthorized = true;
  await assert.rejects(listResources(config), error => error instanceof ApiError && error.status === 401);
});
